<script setup lang="ts">
import { computed, onUnmounted, ref, watch } from "vue";
import { useAuth } from "@papilio/auth";
import { item, request, query, type Page, type SmsSettlementCandidate, type SmsManualApproval, type SmsSettlementReview, type SmsOriginCapabilities } from "@papilio/api";
import { faDate, faNumber, toman } from "@papilio/ui";
const props=defineProps<{eventId:number;capabilities:SmsOriginCapabilities|null}>();
const emit=defineEmits<{busy:[value:boolean]}>();
const auth=useAuth(),review=ref<SmsSettlementReview|null>(null),loading=ref(false),busy=ref(false),error=ref("");
const labels={manual:"Manual review",waiting:"Waiting for a match",ambiguous:"Ambiguous match",approved:"Linked settlement",outside_window:"Outside matching window"};
const candidates=ref<SmsSettlementCandidate[]>([]),candidatePage=ref(1),candidatePages=ref(1),candidateLoading=ref(false),candidateError=ref(""),selected=ref<SmsSettlementCandidate|null>(null),reason=ref(""),pendingBody=ref<SmsManualApproval|null>(null),approvalError=ref(""),approvalNotice=ref("");
const revisionsReady=computed(()=>review.value?.device_revision!=null&&review.value.realm_revision!=null&&review.value.destination_revision!=null);
const canApprove=computed(()=>props.capabilities?.enabled&&auth.can("payments","update")&&review.value?.manual_approval_available&&selected.value?.selectable&&revisionsReady.value&&reason.value.trim().length>0);
let alive=true,sequence=0,candidateSequence=0;
async function loadCandidates():Promise<void>{if(!props.capabilities?.capacity)return;const id=props.eventId,key=++candidateSequence;candidateLoading.value=true;candidateError.value="";try{const result=await request<Page<SmsSettlementCandidate>>(`/v1/admin/payments/sms-origins/sms-events/${id}/candidates?${query({page:candidatePage.value})}`);if(!alive||key!==candidateSequence||props.eventId!==id)return;candidates.value=result.data;candidatePages.value=result.meta.pager?.total_pages??1;}catch(cause){if(alive&&key===candidateSequence)candidateError.value=failure(cause);}finally{if(alive&&key===candidateSequence)candidateLoading.value=false;}}
function choose(row:SmsSettlementCandidate):void{if(busy.value||pendingBody.value||!row.selectable)return;selected.value=row;approvalError.value="";approvalNotice.value="";}
function adoptRevisions():void{const body=pendingBody.value,current=review.value;if(!body||!current||!revisionsReady.value||busy.value||current.status==='approved')return;pendingBody.value={...body,expected_device_revision:current.device_revision!,expected_realm_revision:current.realm_revision!,expected_destination_revision:current.destination_revision!};}
async function approve():Promise<void>{if(busy.value||!props.capabilities?.enabled||!auth.can("payments","update"))return;if(!pendingBody.value){if(!canApprove.value||!selected.value||!review.value)return;pendingBody.value={topup_id:selected.value.topup_id,expected_device_revision:review.value.device_revision!,expected_realm_revision:review.value.realm_revision!,expected_destination_revision:review.value.destination_revision!,reason:reason.value.trim()};}const id=props.eventId,body={...pendingBody.value},key=++sequence;loading.value=false;busy.value=true;emit("busy",true);approvalError.value="";approvalNotice.value="";try{const result=await item<SmsSettlementReview>(`/v1/admin/payments/sms-origins/sms-events/${id}/approve`,"POST",body);if(!alive||props.eventId!==id||key!==sequence)return;if(result.sms_event_id!==id||result.status==='approved'&&result.topup_id!==body.topup_id)throw new Error("The approval response does not match this SMS and selected payment. Reload the recorded decision; your draft is retained.");review.value=result;if(result.status==='approved'){pendingBody.value=null;approvalNotice.value=result.topup_id===body.topup_id?'The SMS is linked to the recorded settlement. Existing approved credit is not credited again.':'This SMS is already linked to a different recorded payment. Review the recorded settlement.';}else approvalNotice.value='The server retained this payment under review. No successful settlement is being reported.';await loadCandidates();}catch(cause){if(alive)approvalError.value=failure(cause);}finally{if(alive){busy.value=false;emit("busy",false);}}}

function failure(cause:unknown):string{return cause instanceof Error?cause.message:"Could not read the settlement review.";}
async function load():Promise<void>{const id=props.eventId,key=++sequence;loading.value=true;error.value="";try{const result=await item<SmsSettlementReview>(`/v1/admin/payments/sms-origins/sms-events/${id}/review`);if(alive&&key===sequence&&props.eventId===id){if(result.sms_event_id!==id)throw new Error("The review response does not match this SMS record.");review.value=result;}}catch(cause){if(alive&&key===sequence)error.value=failure(cause);}finally{if(alive&&key===sequence)loading.value=false;}}
async function check():Promise<void>{if(pendingBody.value||busy.value||!props.capabilities?.enabled||!auth.can("payments","update"))return;const id=props.eventId,key=++sequence;loading.value=false;busy.value=true;emit("busy",true);error.value="";try{const result=await item<SmsSettlementReview>(`/v1/admin/payments/sms-origins/sms-events/${id}/review/refresh`,"POST");if(alive&&key===sequence&&props.eventId===id){if(result.sms_event_id!==id)throw new Error("The review response does not match this SMS record.");review.value=result;}}catch(cause){if(alive&&key===sequence)error.value=failure(cause);}finally{if(alive){busy.value=false;emit("busy",false);}}}
watch(()=>props.eventId,()=>{review.value=null;selected.value=null;pendingBody.value=null;reason.value="";candidatePage.value=1;candidates.value=[];void load();void loadCandidates();},{immediate:true});onUnmounted(()=>{alive=false;++sequence;++candidateSequence;});
</script>
<template><section class="review-section" aria-label="Recorded SMS settlement review"><div class="page-head"><h3>Settlement review</h3><button class="btn secondary" :disabled="loading||busy" @click="load">Reload recorded decision</button></div><p v-if="loading" role="status">Loading recorded settlement decision…</p><p v-if="error" class="message error" role="alert">{{error}}</p><template v-if="review"><p class="hint-box">This is the last recorded settlement decision, separate from captured parsing and source-validation observations. Every settlement action rechecks current ownership, receiving identity and policy.</p><dl class="review-grid"><div><dt>Last recorded decision</dt><dd>{{labels[review.status]}}</dd></div><div><dt>Last checked</dt><dd>{{review.checked_at===null?'Not checked':faDate(review.checked_at)}}</dd></div><div><dt>Current review reason</dt><dd><code>{{review.reason_code??'No recorded hold reason'}}</code></dd></div><div><dt>Recorded candidate count</dt><dd>{{faNumber(review.candidate_count)}}</dd></div><div><dt>Linked payment / settlement</dt><dd>{{review.topup_id===null?'Not linked':'Payment #'+review.topup_id}} / {{review.settlement_id===null?'No settlement':'#'+review.settlement_id}}</dd></div><div><dt>Settlement evidence</dt><dd>{{review.evidence_kind==='bank_reference'?'Bank reference':review.evidence_kind==='trusted_sms_origin'?'Trusted declared SMS origin':'Not recorded'}}</dd></div><div><dt>Current device / revision</dt><dd>{{review.device_id??'Not recorded'}} / {{review.device_revision??'Unavailable'}}</dd></div><div><dt>Current receiving account / revision</dt><dd>{{review.receiving_realm_id??'Not recorded'}} / {{review.realm_revision??'Unavailable'}}</dd></div><div><dt>Current destination / revision</dt><dd>{{review.destination_id??'Not recorded'}} / {{review.destination_revision??'Unavailable'}}</dd></div></dl></template><template v-if="capabilities?.enabled&&auth.can('payments','update')"><p class="hint-box">Running the settlement check can approve an eligible unique match under the configured trust policy. Ambiguous or unsupported evidence remains under review.</p><button class="btn secondary" :disabled="loading||busy||pendingBody!==null" @click="check">Run settlement check</button></template><section v-if="capabilities?.capacity" aria-label="Payment candidates for this SMS"><h3>Payments for this SMS</h3><p class="hint-box">Candidates use the observed amount, receiving account and matching window. Approved credits without a proven account association remain visible for investigation and cannot be selected.</p><p v-if="candidateError" class="message error" role="alert">{{candidateError}}</p><p v-if="candidateLoading" role="status">Loading matching payments…</p><div class="table-wrap"><table class="data-table"><thead><tr><th>Payment / customer</th><th>Amount</th><th>Status</th><th>Association</th><th>Updated</th><th></th></tr></thead><tbody><tr v-for="row in candidates" :key="row.topup_id"><td>Payment #{{row.topup_id}} · Customer #{{row.customer_id}}</td><td>{{toman(row.amount_rial)}}</td><td>{{row.status==='approved'?'Already credited':'Pending payment'}}{{row.already_linked?' · Already linked':''}}</td><td>{{row.association_kind==='captured_realm'?'Captured receiving account':row.association_kind==='immutable_instruction'?'Captured payment instruction':'Unresolved association'}}</td><td>{{faDate(row.updated_at)}}</td><td><button v-if="auth.can('payments','update')" class="btn small secondary" :disabled="busy||pendingBody!==null||!row.selectable||!capabilities.enabled" @click="choose(row)">{{selected?.topup_id===row.topup_id?'Selected':row.selectable?'Select':'Not selectable'}}</button></td></tr></tbody></table></div><p v-if="!candidateLoading&&!candidates.length&&!candidateError">No matching payment candidates.</p><div class="pager"><button :disabled="candidateLoading||busy||candidatePage<=1" @click="candidatePage--;loadCandidates()">‹</button><span>{{faNumber(candidatePage)}} / {{faNumber(candidatePages)}}</span><button :disabled="candidateLoading||busy||candidatePage>=candidatePages" @click="candidatePage++;loadCandidates()">›</button></div><button class="btn secondary" :disabled="candidateLoading||busy" @click="loadCandidates">Reload payment candidates</button><form v-if="selected&&auth.can('payments','update')" class="form-grid" @submit.prevent="approve"><p>Selected payment #{{selected.topup_id}} · {{toman(selected.amount_rial)}} · {{selected.status==='approved'?'Attach the SMS to existing credit; no new credit is requested.':'Approve only after reviewing this SMS and its receiving-account association.'}}</p><label class="field"><span>Manual review reason</span><textarea v-model="reason" maxlength="1000" required :disabled="busy||pendingBody!==null"/></label><p v-if="pendingBody" class="hint-box">The attempted approval is retained for payment #{{pendingBody.topup_id}} with device revision {{pendingBody.expected_device_revision}}, receiving-account revision {{pendingBody.expected_realm_revision}} and destination revision {{pendingBody.expected_destination_revision}}. Retry preserves its payment and reason.</p><p v-if="approvalError" class="message error" role="alert">{{approvalError}}</p><p v-if="approvalNotice" class="message" role="status">{{approvalNotice}}</p><button class="btn" :disabled="busy||!capabilities.enabled||!pendingBody&&!canApprove">{{pendingBody?'Retry retained SMS approval':selected.status==='approved'?'Attach SMS to existing credit':'Approve selected SMS payment'}}</button><button v-if="pendingBody&&revisionsReady&&review?.status!=='approved'" type="button" class="btn secondary" :disabled="busy" @click="adoptRevisions">Use reviewed current revisions for retained approval</button></form></section></section></template>
<style scoped>.review-section{margin-top:24px;padding-top:20px;border-top:1px solid var(--line)}.review-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,220px),1fr));gap:16px}.review-grid dt{color:var(--muted);font-size:.85rem}.review-grid dd{margin:4px 0 0;overflow-wrap:anywhere}</style>
